from lib import *
S = SS('l6')
steps = [
    step("先建一条 5 个提交的链:每个 commit 的 parent 指向前一个(bd38bca 的 parent 是 a36631e,依次往前,提交 1 5c02abe 没有 parent),每个提交各有自己的 tree。", t=tl(S(1)), mark=lidx(S(1), 'bd38bca', 'a36631e'), done=lidx(S(1), 'e8b2f85', '9d8ba3d', '5c02abe'), kv=KV([['提交数', '5 个,一条链'], ['每个 commit', '一个 tree + 一个 parent'], ['记下来', '稍后对比 hash']], ['记下来'])),
    step("用 filter-branch 把提交 2 的说明改一个字(提交 2 → 提交 二)。结果:提交 1 的 hash 没变(5c02abe),提交 2 到提交 5 的 hash 全变了(9d8ba3d→ecc1ba8、e8b2f85→9c72ac6、a36631e→6e92083、bd38bca→dd5eaf2),而提交 3~5 的内容和说明一个字都没动。新历史里每个 parent 指向新的 hash。", t=tl(S(2)), mark=lidx(S(2), '提交 2:', '提交 3:', '提交 4:', '提交 5:'), done=lidx(S(2), '提交 1:', '提交 二'), b=bars([['提交 1', 0, '不变'], ['提交 2', 1, '变'], ['提交 3', 1, '变'], ['提交 4', 1, '变'], ['提交 5', 1, '变']], 1, mark=[1, 2, 3, 4], done=[0]), kv=KV([['被改的提交', 'hash 变'], ['它之前的提交', 'hash 不变'], ['它之后的提交', '内容没动,hash 也全变']], ['它之后的提交'])),
    step("为什么后面的也变:新的提交 3 的原文里 parent 行是 ecc1ba8…(新的提交 2),而 commit 的 hash 是对整个文本算的——parent 行变了,hash 就变。验证:原文里确实包含新提交 2 的 hash(True)。而只改说明时五个 tree 的 hash 完全没变(91c7d88 b08dad9 239ba4d 471da36 bddd827),变的只是 commit 链。", t=tl(S(3)), mark=lidx(S(3), '| parent ecc1ba', '它的 parent 就是新的第 2 个提交: True'), done=lidx(S(3), '91c7d88 b08dad9'), kv=KV([['传播路径', 'parent 行 → commit hash → 下一个 commit 的 parent 行'], ['tree', '只改说明时不变'], ['结论', 'hash 是整条链的指纹']], ['传播路径'])),
    step("改文件内容(只把提交 2 里的“行 2”改成“行 二”):提交 2 的 tree 变了(b08dad9→49913bf);提交 3~5 的 tree 没变(239ba4d、471da36、bddd827,它们的文件里“行 2”没被改),但 commit 的 hash 因为 parent 的变化照样全变。也就是说 tree 层面的变化只影响被改的那一个 commit,commit 层面的变化会传到末端。", t=tl(S(4)), mark=lidx(S(4), '提交 2: commit', '提交 3: commit'), done=lidx(S(4), '提交 1: commit', '提交 4: commit', '提交 5: commit'), kv=KV([['tree 变化', '只影响含改动的那些提交'], ['commit 变化', '一路传到最新'], ['未改的前缀', 'hash 保持不变']], ['commit 变化'])),
    step("改最新的提交(amend 最后一个):提交 1~4 的 hash 都保持原样,只有提交 5 变成 fb51fd1。改的位置越靠后,受影响的越少:改第 2 个影响 4 个(上一节),改第 5 个只影响 1 个。这也是为什么对已经推送的历史改写代价很大——别人的分支基于旧 hash。", t=tl(S(5)), mark=lidx(S(5), '提交 5:'), done=lidx(S(5), '提交 1:', '提交 2:', '提交 3:', '提交 4:'), kv=KV([['改第 k 个', '受影响 6-k 个(共 5 个提交时)'], ['改最新的', '只有 1 个变'], ['已推送的历史', '改写后别人的分支基于旧 hash']], ['改第 k 个'])),
]
A = mkarti('l6', 6, 'Git,hash,Merkle,filter-branch,历史改写,真实验证,动画演示',
    '在 5 个提交的链上改第 2 个提交的一个字:第 1 个 hash 不变,第 2~5 个全变,尽管后三个的内容一个字没动;原因是 parent 行进了 commit 的 hash;只改说明时 tree 完全不变,改文件内容只让被改的那个 tree 变;改最新的提交只影响 1 个。',
    '为什么改一个字,后面所有 commit 的 hash 都变了?这篇用 filter-branch 在一条 5 个提交的链上改说明和文件内容,逐个对比 hash 和 tree,再读新提交的原文验证 parent 行,最后看改最新的提交只影响一个。',
    [('4 / 5', '改提交 2 的一个字,hash 变化的提交数是 4(提交 2 到 5),提交 1 不变'), ('tree 不变', '只改说明时五个 tree 的 hash 一个都没变,变的只有 commit 链'), ('1 个', '改最新的提交,受影响的只有它自己')],
    [('实验设置', '<p>一条 5 个提交的线性历史,每个提交往 <code>f.txt</code> 里多加一行。作者、时间固定,所以每次重做 hash 都一样,便于对照改写前后的变化。</p>'),
     ('改一个字的后果', '<p>把第 2 个提交的说明改一个字:它之前的提交 hash 不变,它自己和它之后的全部提交 hash 都变,即使后面提交的内容和说明一个字没动。</p>'),
     ('传播的原因', '<p>commit 的 hash 是对整个文本算的,文本里有 <code>parent</code> 行。改了前面的提交,它的 hash 变了,后一个提交的 parent 行就必须改成新的 hash,于是后一个提交的 hash 也变,一路传到分支末端。这就是“hash 是历史的指纹”:一个 commit 的 hash 确定了它之前的全部历史,别人拿到旧 hash 就能发现历史被改写过。</p>'),
     ('tree 与 commit 两层', '<p>只改说明时,所有 tree 都不变;改文件内容时只有包含这个改动的 tree 变,后面没碰这个文件的提交 tree 不变(本例中提交 3~5 的 tree 与原来相同)。但 commit 层始终是整条链往后传。</p>'),
     ('改写的代价', '<p>改的位置越早,要重写的提交越多;已经推送出去的历史改写之后,别人本地的分支基于旧 hash,需要强制推送和重新同步。改最新的提交最便宜。</p>')],
    steps,
    [ENV_I_GIT + '。改写用的是 git filter-branch(命令里的警告被截掉了,不影响结果);作者、提交者与时间固定,所以改写前后的 hash 都可复现',
     '没有验证:用 rebase 或 git-filter-repo 改写的 hash 变化(原理相同,没有逐个验证);签名提交改写后签名失效的情形;改写后旧对象何时被回收(见 prune 一篇);有合并提交的非线性历史上的传播范围'],
    'hash 的连锁变化')
